{"implementation": "def solve(case):
    required = set(case['required_failure_items'])
    unresolved = set(case['unresolved_without'])
    minimal = sorted(required | unresolved)
    return {
        "minimal_failure": minimal,
        "outcome": "PASS" if not unresolved else "FAIL",
        "tests": len(minimal)
    }"}
